// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.persona.jitimport timber.log.Timberimport kotlinx.coroutines.CoroutineDispatcherimport kotlinx.coroutines.asyncimport kotlinx.coroutines.coroutineScopeimport kotlinx.coroutines.withTimeoutOrNull/** * NOUS — JIT Context Fetcher (Module 15 v3.0 — Step 15.2). * * The **Just-In-Time** context orchestrator. Fires **only** during the * 300ms wake-word STT gap — zero background polling, zero wakelock drain. * * ## Execution flow (per strategy §4) * * ``` * User speaks: "Hey NOUS..." * Module 5 STT begins processing (~300-500ms) * SIMULTANEOUSLY: *   JitContextFetcher.fetch() *     ├── async: BatteryObserver.fetch()       (< 10ms) *     ├── async: MediaObserver.fetch()         (< 30ms) *     ├── async: CallLogObserver.fetch()       (< 50ms) *     ├── async: UsageStatsObserver.fetch()    (< 50ms) *     └── async: InteractionGapCalculator       (< 1ms) *   All parallel — total < 100ms (well within 300ms gap) * By the time STT outputs the text intent: *   → JitContextPayload is fully assembled *   → Gossip triggers evaluated *   → Payload injected into LLM prompt * ``` * * ## Timeout * * Each observer call is wrapped in a 200ms timeout. If any observer is * slow (e.g., CallLog content provider is busy), its result is silently * dropped — we don't delay the LLM prompt for one slow observer. * * ## Gossip triggers (per strategy §4 "Gossip Triggers") * * After assembling the payload, the fetcher evaluates 4 gossip triggers: *  1. **BATTERY_HUNGRY** — battery < 15% + not charging. *  2. **MUSIC_MOOD** — sad genre → empathy, dance → hype. *  3. **USER_NEGLECT** — last interaction > 12 hours ago. *  4. **SOCIAL_CHECK** — frequent contact didn't call today. * * Only triggers that fire are included in the payload — the LLM decides * whether to mention them (persona-dependent). * * @see <a href="docs/strategy/module-15-digital-soul-strategy.md">§4 JIT Ambient Observer</a> */class JitContextFetcher(    private val batteryObserver: BatteryObserver,    private val mediaObserver: MediaObserver,    private val callLogObserver: CallLogObserver,    private val usageStatsObserver: UsageStatsObserver,    private val interactionGapProvider: () -> Long? = { null },    private val dispatcher: CoroutineDispatcher,) {    /**     * Fetch all context in parallel during the STT gap.     *     * Returns a fully assembled [JitContextPayload] with gossip triggers     * evaluated, or a payload with nulls if observers failed/timed out.     */    suspend fun fetch(): JitContextPayload {        Timber.tag(TAG).d("JIT fetch starting (300ms STT gap).")        val payload = coroutineScope {            // All 5 fetches run in parallel — each with a 200ms timeout.            val batteryDeferred = async(dispatcher) {                withTimeoutOrNull(OBSERVER_TIMEOUT_MS) { batteryObserver.fetch() }            }            val mediaDeferred = async(dispatcher) {                withTimeoutOrNull(OBSERVER_TIMEOUT_MS) { mediaObserver.fetch() }            }            val callLogDeferred = async(dispatcher) {                withTimeoutOrNull(OBSERVER_TIMEOUT_MS) { callLogObserver.fetch() }            }            val usageStatsDeferred = async(dispatcher) {                withTimeoutOrNull(OBSERVER_TIMEOUT_MS) { usageStatsObserver.fetch() }            }            val gapDeferred = async(dispatcher) {                withTimeoutOrNull(OBSERVER_TIMEOUT_MS) { interactionGapProvider() }            }            JitContextPayload(                battery = batteryDeferred.await(),                media = mediaDeferred.await(),                callLog = callLogDeferred.await(),                appUsage = usageStatsDeferred.await(),                interactionGapMs = gapDeferred.await(),            )        }        // Evaluate gossip triggers.        val triggers = GossipTriggerEvaluator.evaluate(payload)        val result = payload.copy(gossipTriggers = triggers)        Timber.tag(TAG).d("JIT fetch complete: battery=${result.battery?.level}%, " +            "media=${result.media?.track}, triggers=${triggers.size}.")        return result    }    private companion object {        private const val TAG = "JitContextFetcher"        private const val OBSERVER_TIMEOUT_MS = 200L    }}// ──────────────────────────────────────────────────────────────────────────/** * Evaluates gossip triggers on a [JitContextPayload]. * * Per strategy §4 "Gossip Triggers" — 4 trigger types: *  1. BATTERY_HUNGRY — battery < 15% + not charging. *  2. MUSIC_MOOD — sad genre → empathy, dance → hype. *  3. USER_NEGLECT — last interaction > 12 hours ago. *  4. SOCIAL_CHECK — frequent contact didn't call today. * * Pure function — fully testable without Android. */object GossipTriggerEvaluator {    /** Battery threshold for BATTERY_HUNGRY trigger (per strategy §4). */    const val BATTERY_HUNGRY_THRESHOLD = 15    /** Interaction gap for USER_NEGLECT trigger (12 hours in ms). */    const val NEGLECT_THRESHOLD_MS = 12L * 60 * 60 * 1000    /** Music genres that trigger EMPATHY mode. */    val SAD_GENRES = setOf("sad", "blues", "melancholy", "acoustic", "classical", "ballad")    /** Music genres that trigger HYPE mode. */    val HYPE_GENRES = setOf("dance", "edm", "electronic", "party", "hip hop", "rap", "rock")    /**     * Evaluate all gossip triggers on [payload].     *     * @return list of fired triggers (empty if none).     */    fun evaluate(payload: JitContextPayload): List<GossipTriggerResult> {        val results = mutableListOf<GossipTriggerResult>()        // 1. BATTERY_HUNGRY.        payload.battery?.let { battery ->            if (battery.isLow && !battery.isCharging) {                results.add(GossipTriggerResult(                    type = GossipTriggerType.BATTERY_HUNGRY,                    hint = "The user's battery is at ${battery.level}%. Suggest charging gently.",                    priority = 8,                ))            }        }        // 2. MUSIC_MOOD.        payload.media?.let { media ->            when {                media.genre in SAD_GENRES -> results.add(GossipTriggerResult(                    type = GossipTriggerType.MUSIC_MOOD,                    hint = "The user is listening to sad music (${media.track}). Be extra empathetic.",                    priority = 5,                ))                media.genre in HYPE_GENRES -> results.add(GossipTriggerResult(                    type = GossipTriggerType.MUSIC_MOOD,                    hint = "The user is listening to energetic music (${media.track}). Match the energy.",                    priority = 5,                ))            }        }        // 3. USER_NEGLECT.        payload.interactionGapMs?.let { gap ->            if (gap >= NEGLECT_THRESHOLD_MS) {                val hours = gap / 3_600_000                results.add(GossipTriggerResult(                    type = GossipTriggerType.USER_NEGLECT,                    hint = "It's been $hours hours since the user last talked to you. Welcome them back.",                    priority = 6,                ))            }        }        // 4. SOCIAL_CHECK.        payload.callLog?.let { log ->            if (log.missedFromFrequent.isNotEmpty()) {                val names = log.missedFromFrequent.joinToString(limit = 3)                results.add(GossipTriggerResult(                    type = GossipTriggerType.SOCIAL_CHECK,                    hint = "These frequent contacts haven't called today: $names. Consider checking in.",                    priority = 4,                ))            }        }        // Sort by priority descending — highest priority mentioned first.        return results.sortedByDescending { it.priority }    }}
